     *                                            operation that declares several 2xx responses
     *                                            (a status such as 201, or a range such as 2XX).
     *                                            A success body is decoded as the type of its
     *                                            actual status and wrapped in $returnType, the
     *                                            union. Empty for every other operation.
     * @param list<list<string>>    $securityRequirements The operation's security requirement:
     *                                            alternatives of scheme ids that must all be
     *                                            configured. Read only when per-scheme credentials
     *                                            are configured.
     * @param array<int|string, \Closure(int, array<string, string>|null, string|null, string|null, string|null): ApiException> $errorSchemas
     *                                            Factory of the error type of each error schema
     *                                            the operation declares, by declared status (404,
     *                                            4XX or default). Empty when it declares none.
     * @param string|null           $operationId  The operation id exactly as written in the OpenAPI
     *                                            document, handed to the call hook
     * @param string|null           $urlTemplate  The path template of the operation, handed to the call hook
     *
     *
     * @return ApiResult<mixed>
     * @throws ApiException
     */
    private function invokeCall(
        bool $stream,
        string $method,
        string $path,
        array $queryParams,
        array $headerParams,
        mixed $body,
        array $accepts,
        ?string $contentType,
        ?string $returnType,
        ?Authenticator $auth = null,
        array $allowReservedKeys = [],
        bool $rawBody = false,
        ?int $timeout = null,
        ?array $headers = null,
        ?int $maxRetries = null,
        array $successTypes = [],
        array $securityRequirements = [],
        array $errorSchemas = [],
        ?string $operationId = null,
        ?string $urlTemplate = null,
        ?int $idleTimeoutMs = null
    ): ApiResult {
        $this->lifecycle?->assertOpen();
        $callHeaders = $headers;
        if ($timeout !== null && $timeout <= 0) {
            throw new \InvalidArgumentException(
                "Invalid timeout: must be a positive number of milliseconds (got $timeout)"
            );
        }
        if ($maxRetries !== null && $maxRetries < 0) {
            throw new \InvalidArgumentException(
                "Invalid maxRetries: must not be negative (got $maxRetries)"
            );
        }
        /* The opt-in constraint check runs before anything is built or sent, so
         * a refused body never reaches the call hook or the transport. */
        if ($this->config->validateConstraints && $body !== null) {
            ConstraintValidator::validate($body);
        }
        if (str_starts_with($path, 'http://') || str_starts_with($path, 'https://')) {
            $url = $path;
        } else {
            /* Strip trailing slash from baseUrl when path starts with `/` so
             * baseUrl='https://x/' + path='/y' produces 'https://x/y', not
             * 'https://x//y' which most servers route to 404. */
            $base = str_starts_with($path, '/') ? rtrim($this->config->baseUrl, '/') : $this->config->baseUrl;
            $url = $base . $path;
        }

        /* Three-state auth resolution (the heart of the security:[] fix):
         *   - $auth IS the NoAuth sentinel  -> NO auth applied; do NOT fall
         *     back to the client authenticator. The operation was declared
         *     `security: []` (explicitly unauthenticated), so attaching the
         *     client credential here would leak it (e.g. to a reflecting
         *     testEcho* endpoint).
         *   - $auth is null                 -> fall back to the client-level
         *     authenticator (secured op with no per-call override).
         *   - $auth is a real Authenticator -> use it (per-call override).
         * The sentinel is compared by identity (`===`) so it can never be
         * confused with a real authenticator instance. */
        if ($auth === NoAuth::instance()) {
            $effectiveAuth = null;
        } else {
            if ($auth instanceof \PetstoreClient\Auth\Authenticator) {
                $effectiveAuth = $auth;
            } elseif ($this->schemeAuthenticators !== []) {
                $effectiveAuth = $this->schemeAuthenticatorFor($securityRequirements);
            } else {
                $effectiveAuth = $this->authenticator;
            }
        }
        if ($auth instanceof \PetstoreClient\Auth\Authenticator && $effectiveAuth instanceof HttpAwareAuthenticator) {
            /* A per-call authenticator never went through the Client
             * constructor, so it has no transport for its token requests yet. */
            $effectiveAuth->setApiClient($this->apiClient);
        }
        if ($effectiveAuth instanceof Authenticator) {
            foreach ($effectiveAuth->getQueryParams() as $k => $v) {
                $queryParams[$k] = $v;
            }
        }

        $query = $this->buildQuery($queryParams, false, $allowReservedKeys);
        if ($query !== '') {
            /* A next-page URL taken from a Link header already carries a query. */
            $url .= (str_contains($url, '?') ? '&' : '?') . $query;
        }

        $isMultipart = $contentType === 'multipart/form-data';
        /* Builds the headers of one attempt. A retry calls it again, so every
         * attempt is a fresh request carrying the authenticator's current
         * headers (a token refreshed meanwhile is picked up). */
        $buildHeaders = function () use (
            $accepts,
            $contentType,
            $isMultipart,
            $headerParams,
            $effectiveAuth,
            $callHeaders,
            $method,
            $url,
        ): array {
            $headers = $this->headerSelector->selectHeaders($accepts, $contentType ?? '', $isMultipart);
            $headers = $this->mergeHeaders($headers, $this->config->defaultHeaders);
            $headers = $this->mergeHeaders($headers, $headerParams);
            if ($effectiveAuth instanceof Authenticator) {
                $headers = $this->mergeHeaders($headers, $effectiveAuth->getAuthHeaders());
                $cookies = $effectiveAuth->getCookieParams();
                if ($cookies !== []) {
                    /* RFC 6265 — don't URL-encode cookie name/value; most cookie
                     * parsers don't URL-decode, so `=` (base64 padding) would
                     * arrive as literal `%3D` and break JWT/session cookies.
                     * Validate and pass through raw instead. */
                    $cookieParts = [];
                    foreach ($cookies as $k => $v) {
                        if (preg_match('/\A[A-Za-z0-9!#$%&\'*+\-.^_`|~]+\z/', $k) !== 1) {
                            throw new \InvalidArgumentException(
                                "Cookie name '$k' contains characters forbidden by RFC 6265"
                            );
                        }
                        if (preg_match('/\A[!\x23-\x2B\x2D-\x3A\x3C-\x5B\x5D-\x7E]*\z/', $v) !== 1) {
                            throw new \InvalidArgumentException(
                                "Cookie value for '$k' contains characters forbidden by RFC 6265"
                            );
                        }
                        $cookieParts[] = $k . '=' . $v;
                    }
                    $cookieStr = implode('; ', $cookieParts);
                    $existing = $headers['Cookie'] ?? '';
                    $headers['Cookie'] = $existing !== '' ? $existing . '; ' . $cookieStr : $cookieStr;
                }
                /* A digest authenticator answers the challenge it remembers (D192). */
                if ($effectiveAuth instanceof DigestAuthenticator) {
                    $answer = $effectiveAuth->authorization(strtoupper($method), $this->requestTarget($url));
                    if ($answer !== null) {
                        $headers = $this->mergeHeaders($headers, ['Authorization' => $answer]);
                    }
                }
            }
            foreach ($callHeaders ?? [] as $name => $value) {
                foreach (array_keys($headers) as $existing) {
                    if (strcasecmp((string) $existing, (string) $name) === 0) {
                        unset($headers[$existing]);
                    }
                }
                $headers[$name] = $value;
            }
            TraceContextUtil::injectTraceContext($headers);

            return $headers;
        };

        $noBody = $body === null;
        $headersForAttempt = function () use ($buildHeaders, $noBody): array {
            $built = $buildHeaders();
            if ($noBody) {
                /* No body means no entity: never announce a Content-Type for it. */
                foreach (array_keys($built) as $name) {
                    if (strtolower((string) $name) === 'content-type') {
                        unset($built[$name]);
                    }
                }
            }

            return $built;
        };

        /* The call hook runs once per call, after the trace context is injected, so the
         * header set it sees is final. What it changes is kept as a delta and applied to
         * the headers of every later attempt, which are rebuilt from scratch. */
        $observer = null;
        $callHook = $this->config->getCallHook();
        if ($callHook instanceof \PetstoreClient\CallHook) {
            $initialHeaders = $headersForAttempt();
            $headersBeforeHook = $initialHeaders;
            $observer = $callHook->start(
                new CallInfo(
                    $operationId ?? '',
                    $method,
                    $urlTemplate ?? '',
                    $this->urlWithoutQuery($url),
                    $this->serverAddress($url)
                ),
                $initialHeaders
            );
            $rebuildHeaders = $headersForAttempt;
            $attempts = 0;
            $headersForAttempt = function () use ($rebuildHeaders, $headersBeforeHook, $initialHeaders, &$attempts): array {
                if ($attempts++ === 0) {
                    return $initialHeaders;
                }

                return $this->applyHeaderEdits($rebuildHeaders(), $headersBeforeHook, $initialHeaders);
            };
        }

        $statusCode = 0;
        $responseHeaders = null;
        try {
            $serializedBody = $this->serializeBody($body, $contentType, $isMultipart, $rawBody, $allowReservedKeys);

            if ($stream) {
                $result = $this->openStream(
                    $method,
                    $url,
                    $headersForAttempt,
                    $serializedBody,
                    $timeout,
                    $maxRetries,
                    $effectiveAuth,
                    $errorSchemas,
                    $statusCode,
                    $responseHeaders,
                    $idleTimeoutMs
                );
            } else {
                /* A transport that derives from AbstractApiClient also retries a
                 * transient failure (TransportOptions::$maxRetries); any other
                 * ApiClient implementation sends once. */
                $response = $this->apiClient instanceof AbstractApiClient
                    ? $this->apiClient->sendWithRetries(
                        $method,
                        $url,
                        $headersForAttempt,
                        $serializedBody,
                        $timeout,
                        $maxRetries
                    )
                    : $this->apiClient->sendRequest($method, $url, $headersForAttempt(), $serializedBody);
                $statusCode = $response->statusCode;
                $responseHeaders = $response->headers;

                if (
                    $response->statusCode === 401
                    && $effectiveAuth instanceof Authenticator
                    && method_exists($effectiveAuth, 'invalidateAccessToken')
                    && $this->isReplayableBody($serializedBody)
                ) {
                    /* A revoked or rotated token keeps failing while it is cached.
                     * Drop it, obtain a new one (a refresh grant first) and replay the
                     * request once. A body that cannot be replayed (a stream) is not
                     * retried, and a failed re-authentication leaves the 401 as is. */
                    $effectiveAuth->invalidateAccessToken();
                    try {
                        $retryAuthHeaders = $effectiveAuth->getAuthHeaders();
                    } catch (\PetstoreClient\Errors\OpenAPIException) {
                        $retryAuthHeaders = null;
                    }
                    if ($retryAuthHeaders !== null) {
                        $response = $this->apiClient->sendRequest(
                            $method,
                            $url,
                            array_merge($headersForAttempt(), $retryAuthHeaders),
                            $serializedBody
                        );
                        $statusCode = $response->statusCode;
                        $responseHeaders = $response->headers;
                    }
                }

                if (
                    $response->statusCode === 401
                    && $effectiveAuth instanceof DigestAuthenticator
                    && $this->isReplayableBody($serializedBody)
                    && $this->acceptsChallenge($effectiveAuth, $response->headers)
                ) {
                    /* HTTP Digest (D192): the challenge is answered and the request
                     * replayed once; a second 401 stands. */
                    $response = $this->apiClient->sendRequest($method, $url, $headersForAttempt(), $serializedBody);
                    $statusCode = $response->statusCode;
                    $responseHeaders = $response->headers;
                }

                if ($response->statusCode < 200 || $response->statusCode >= 300) {
                    throw ApiException::fromResponse(
                        $response->statusCode,
                        $response->headers,
                        $response->body,
                        $method,
                        $url,
                        $errorSchemas
                    );
                }

                try {
                    $data = $this->decodeSuccessBody($response, $returnType, $successTypes, $operationId);
                } catch (SerializationException $e) {
                    throw $e->withResponse(
                        $response->statusCode,
                        $response->headers,
                        $response->body,
                        $method,
                        $url
                    );
                }

                $result = new ApiResult($response->statusCode, $data, $response->body, $response->headers);
            }
        } catch (\Throwable $error) {
            $this->finishCall($observer, $statusCode, $responseHeaders, $error);
            throw $error;
        }
        $this->finishCall($observer, $statusCode, $responseHeaders, null);

        return $result;
    }

    /** The most of an error body a stream call reads before it raises the error. */
    private const int STREAM_ERROR_BODY_LIMIT = 65536;

    /**
     * Send the request for a stream result: a success hands back the open stream, any other status
     * reads a bounded part of its body, closes it and raises the typed error of a buffered call.
     *
     * @param \Closure(): array<string, string> $headersForAttempt builds the request headers for one attempt
     * @param array<int|string, \Closure(int, array<string, string>|null, string|null, string|null, string|null): ApiException> $errorSchemas
     * @param int                         $statusCode      set to the status that arrived
     * @param array<string, string>|null  $responseHeaders set to the headers that arrived
     * @param-out int                     $statusCode
     * @param-out array<string, string>   $responseHeaders
     *
     * @return ApiResult<ByteStream> the result whose data is the open stream; its raw body is empty
     *
     * @throws ApiException when the status is not 2xx
     */
    private function openStream(
        string $method,
        string $url,
        \Closure $headersForAttempt,
        mixed $serializedBody,
        ?int $timeout,
        ?int $maxRetries,
        ?Authenticator $effectiveAuth,
        array $errorSchemas,
        int &$statusCode,
        ?array &$responseHeaders,
        ?int $idleTimeoutMs = null,
    ): ApiResult {
        $stream = $this->callStreaming(
            $method,
            $url,
            $headersForAttempt,
            $serializedBody,
            $timeout,
            $maxRetries,
            $idleTimeoutMs
        );
        $statusCode = $stream->statusCode;
        $responseHeaders = $stream->headers;

        if (
            $stream->statusCode === 401
            && $effectiveAuth instanceof Authenticator
            && method_exists($effectiveAuth, 'invalidateAccessToken')
            && $this->isReplayableBody($serializedBody)
        ) {
            /* The same replay as a buffered call: drop the cached token, obtain a new one and send
             * the request once more. The refused response is closed unread. */
            $effectiveAuth->invalidateAccessToken();
            try {
                $retryAuthHeaders = $effectiveAuth->getAuthHeaders();
            } catch (\PetstoreClient\Errors\OpenAPIException) {
                $retryAuthHeaders = null;
            }
            if ($retryAuthHeaders !== null) {
                $stream->close();
                $stream = $this->callStreaming(
                    $method,
                    $url,
                    static fn (): array => array_merge($headersForAttempt(), $retryAuthHeaders),
                    $serializedBody,
                    $timeout,
                    $maxRetries,
                    $idleTimeoutMs
                );
                $statusCode = $stream->statusCode;
                $responseHeaders = $stream->headers;
            }
        }

        if (
            $stream->statusCode === 401
            && $effectiveAuth instanceof DigestAuthenticator
            && $this->isReplayableBody($serializedBody)
            && $this->acceptsChallenge($effectiveAuth, $stream->headers)
        ) {
            $stream->close();
            $stream = $this->callStreaming(
                $method,
                $url,
                $headersForAttempt,
                $serializedBody,
                $timeout,
                $maxRetries,
                $idleTimeoutMs
            );
            $statusCode = $stream->statusCode;
            $responseHeaders = $stream->headers;
        }

        if ($stream->statusCode < 200 || $stream->statusCode >= 300) {
            $bytes = $stream->readBounded(self::STREAM_ERROR_BODY_LIMIT);
            throw ApiException::fromResponse(
                $stream->statusCode,
                $stream->headers,
                $this->errorBodyText($bytes, $stream->headers),
                $method,
                $url,
                $errorSchemas
            );
        }

        $this->lifecycle?->track($stream);

        return new ApiResult($stream->statusCode, $stream, '', $stream->headers);
    }

    /**
     * Sends a streaming request through the transport: a transport that derives from AbstractApiClient
     * retries and rebuilds the headers of every attempt, any other {@see StreamingApiClient} is sent
     * once, and a transport that cannot stream fails the call, never falling back to buffering.
     *
     * @param \Closure(): array<string, string> $headers builds the request headers for one attempt
     *
     * @throws \BadMethodCallException when the transport does not implement {@see StreamingApiClient}
     */
    private function callStreaming(
        string $method,
        string $url,
        \Closure $headers,
        mixed $body,
        ?int $timeout,
        ?int $maxRetries,
        ?int $idleTimeoutMs = null,
    ): ByteStream {
        if ($this->apiClient instanceof AbstractApiClient) {
            return $this->apiClient->sendStreamingWithRetries(
                $method,
                $url,
                $headers,
                $body,
                $timeout,
                $maxRetries,
                $idleTimeoutMs
            );
        }
        if ($this->apiClient instanceof StreamingApiClient) {
            return $this->apiClient->sendStreaming($method, $url, $headers(), $body, $timeout, $maxRetries, $idleTimeoutMs);
        }

        throw new \BadMethodCallException(
            $this->apiClient::class . ' cannot stream: it does not implement StreamingApiClient::sendStreaming,'
            . ' so an operation that returns a stream cannot be called through it'
        );
    }

    /**
     * The body of an error response as a buffered call hands it over: the decoded text for a text
     * content type, and base64 text for anything else.
     *
     * @param array<string, string> $headers the response headers, lower-cased
     */
    private function errorBodyText(string $bytes, array $headers): string
    {
        $contentType = $headers['content-type'] ?? '';
        $mediaType = trim(explode(';', $contentType)[0]);
        if ($mediaType !== '' && !$this->isTextMediaType($mediaType)) {
            return base64_encode($bytes);
        }
        if (
            preg_match('/charset\s*=\s*"?([^";\s]+)/i', $contentType, $found) === 1
            && !in_array(strtolower($found[1]), ['utf-8', 'utf8'], true)
            && function_exists('mb_convert_encoding')
        ) {
            try {
                $converted = mb_convert_encoding($bytes, 'UTF-8', $found[1]);
                if ($converted !== false) {
                    return $converted;
                }
            } catch (\ValueError) {
                /* an unknown charset: the bytes are handled as UTF-8 */
            }
        }

        return function_exists('mb_scrub') ? mb_scrub($bytes, 'UTF-8') : $bytes;
    }

    /**
     * Tell the observer of the call hook how the call ended. An exception thrown by
     * the observer is swallowed, so the call still returns its result or its own error.
     *
     * @param CallObserver|null          $observer   the observer {@see CallHook::start()} returned, if any
     * @param int                        $statusCode the status that arrived, or 0
     * @param array<string, string>|null $headers    the response headers, or null when no response arrived
     * @param \Throwable|null            $error      the error the caller receives, or null on success
     */
    private function finishCall(
        ?CallObserver $observer,
        int $statusCode,
        ?array $headers,
        ?\Throwable $error
    ): void {
        if (!$observer instanceof \PetstoreClient\CallObserver) {
            return;
        }
        try {
            $observer->finish(
                new CallOutcome($statusCode, $headers === null ? null : array_change_key_case($headers, CASE_LOWER), $error)
            );
        } catch (\Throwable) {
        }
    }

    /**
     * What the call hook changed in the headers: the headers it added or changed, and the
     * names it removed, applied to a freshly built header set.
     *
     * @param array<string, string> $fresh  the headers of this attempt, built from scratch
     * @param array<string, string> $before the headers of the first attempt before the hook ran
     * @param array<string, string> $after  the headers of the first attempt after the hook ran
     *
     * @return array<string, string> the headers of this attempt with the edits of the hook
     */
    private function applyHeaderEdits(array $fresh, array $before, array $after): array
    {
        foreach (array_keys($before) as $name) {
            if (!array_key_exists($name, $after)) {
                unset($fresh[$name]);
            }
        }
        foreach ($after as $name => $value) {
            if (array_key_exists($name, $before) && $before[$name] === $value) {
                continue;
            }
            foreach (array_keys($fresh) as $existing) {
                if (strcasecmp((string) $existing, (string) $name) === 0) {
                    unset($fresh[$existing]);
                }
            }
            $fresh[$name] = $value;
        }

        return $fresh;
    }

    /**
     * The request URL without its query string and fragment.
     */
    private function urlWithoutQuery(string $url): string
    {
        $end = strcspn($url, '?#');

        return substr($url, 0, $end);
    }

    /**
     * The host of the request URL, lower-case, without port and without the brackets of
     * an IPv6 literal.
     */
    private function serverAddress(string $url): string
    {
        $host = parse_url($this->urlWithoutQuery($url), PHP_URL_HOST);

        return is_string($host) ? strtolower(trim($host, '[]')) : '';
    }

    /**
     * Decode the body of a successful response as the return type of the operation.
     *
     * @param ApiHttpResponse           $response     the successful response
     * @param string|null               $returnType   the return type of the operation
     * @param array<int|string, string> $successTypes the model type of each success status
     *                                                of an operation with several 2xx responses
     * @param string|null               $operationId  the operation id, named in an unexpected-content-type error
     *
     * @return mixed the decoded body, or null for an empty body
     * @throws SerializationException when the body cannot be decoded as the return type
     */
    private function decodeSuccessBody(ApiHttpResponse $response, ?string $returnType, array $successTypes, ?string $operationId = null): mixed
    {
        $data = null;
        if (trim($response->body) !== '') {
            $respContentType = null;
            foreach ($response->headers as $name => $value) {
                if (strtolower($name) === 'content-type') {
                    $respContentType = explode(';', $value)[0];
                    $respContentType = trim($respContentType);
                    break;
                }
            }

            $isNonJson = $respContentType !== null
                && !$this->headerSelector->isJsonMime($respContentType);

            if (
                $isNonJson && $returnType !== null && $returnType !== 'string'
                && $this->isTextMediaType((string) $respContentType)
            ) {
                /* A model, number or collection cannot be built from a
                 * non-JSON text body, and handing back the raw string in its
                 * place would give the caller the wrong type. */
                throw new SerializationException(
                    "Unexpected response Content-Type '" . $respContentType
                        . "' for " . (new \ReflectionClass($this))->getShortName() . '.' . ($operationId ?? '')
                        . ': expected a JSON body'
                );
            }
            /* A void operation has no return type and ignores a non-JSON success body. */
            if ($isNonJson && $returnType === null) {
                $data = null;
            } elseif ($isNonJson && $this->isTextMediaType((string) $respContentType)) {
                /* A text response (text/plain, XML, ...) crosses the
                 * transport as its decoded string, never base64: hand it
                 * back unchanged. Base64-decoding it would corrupt any text
                 * that happens to be valid base64 ("hello world"). */
                $data = $response->body;
            } elseif ($isNonJson) {
                /* The transport (DefaultApiClient) base64-encodes every
                 * non-text response body so it survives transit as a UTF-8
                 * string. A binary operation's return type is the raw byte
                 * string (`string` in PHP), so we must base64-DECODE here to
                 * hand the caller the original bytes — not the base64 text.
                 * This mirrors the byte-oriented SDKs (e.g. Python decodes
                 * when return_type == 'bytes'). Strict decoding rejects any
                 * non-base64 input; if a test server wrote raw bytes instead
                 * of base64 (so strict decode returns false), fall back to
                 * the untouched body. Text responses are handled above, so
                 * the decode never touches a text/plain payload. */
                $decoded = base64_decode($response->body, true);
                $data = $decoded === false ? $response->body : $decoded;
            } elseif ($returnType === 'string' && is_array(json_decode($response->body, true))) {
                /* A binary operation that also declares application/json (content
                 * negotiation) can be answered with a JSON document, which is not a
                 * string: hand back its raw bytes, as every SDK does, instead of
                 * letting the string cast turn the decoded array into "Array". */
                $data = $response->body;
            } elseif ($returnType !== null) {
                $variantType = $successTypes[$response->statusCode]
                    ?? $successTypes[intdiv($response->statusCode, 100) . 'XX']
                    ?? null;
                if ($variantType !== null) {
                    /* An operation with several 2xx responses decodes the body
                     * as the schema of the status that arrived, then wraps it
                     * in the result union, never by trying each variant. */
                    /** @var class-string $returnType */
                    $data = new $returnType(ObjectSerializer::deserialize($response->body, $variantType, []));
                } else {
                    $data = ObjectSerializer::deserialize($response->body, $returnType, []);
                }
            }
        }

        return $data;
    }

    /**
     * Invoke an API operation.
     *
     * @param string                $method       HTTP method (GET, POST, PUT, DELETE, etc.)
     * @param string                $path         URL path (with path params already substituted)
     * @param array<string, mixed>  $queryParams  Query parameters
     * @param array<string, string> $headerParams Custom header parameters
     * @param mixed                 $body         Request body (model object or form params array)
     * @param string[]              $accepts      Acceptable response content types
     * @param string|null           $contentType  Request content type
     * @param string|null           $returnType   Return type for deserialization
     * @param Authenticator|null    $auth         Three-state auth selector: the NoAuth sentinel
     *                                            suppresses all credentials (security:[] operation);
     *                                            null falls back to the client authenticator (secured
     *                                            op, no per-call override); a real Authenticator is a
     *                                            per-call override
     * @param array<string, bool>   $allowReservedKeys Set of query parameter
     *                                            names (baseName => true) declared
     *                                            `allowReserved: true`; their values
     *                                            keep RFC 3986 reserved characters
     *                                            literal. Empty by default, so
     *                                            omitting it encodes every value as
     *                                            before.
     * @param bool                  $rawBody      True when the operation's body is
     *                                            `format: binary`: the caller's bytes,
     *                                            file or stream go on the wire verbatim
     *                                            under whichever declared Content-Type
     *                                            was selected, even application/json.
     *
     * @return mixed Deserialized response or null
     * @throws ApiException
     */
    protected function invokeApi(
        string $method,
        string $path,
        array $queryParams,
        array $headerParams,
        mixed $body,
        array $accepts,
        ?string $contentType,
        ?string $returnType,
        ?Authenticator $auth = null,
        array $allowReservedKeys = [],
        bool $rawBody = false
    ): mixed {
        return $this->invokeApiForResult(
            $method,
            $path,
            $queryParams,
            $headerParams,
            $body,
            $accepts,
            $contentType,
            $returnType,
            $auth,
            $allowReservedKeys,
            $rawBody
        )->data;
    }

    /**
     * Folds an operation's cookie parameters into one Cookie request header,
     * in declaration order. No header is added when the call sends no cookie.
     *
     * @param array<string, string> $headerParams the request headers built so far
     * @param list<string>          $cookieParts  the encoded `name=value` pairs
     * @return array<string, string> the headers with the Cookie header added
     */
    protected static function withCookieHeader(array $headerParams, array $cookieParts): array
    {
        if ($cookieParts !== []) {
            $headerParams['Cookie'] = implode('; ', $cookieParts);
        }
        return $headerParams;
    }

    /**
     * Merges header maps so that a name in any casing replaces the same name
     * already present (RFC 9110 section 5.1): one field is never sent twice.
     *
     * @param array<string, string> $base
     * @param array<string, string> $overrides
     * @return array<string, string>
     */
    private function mergeHeaders(array $base, array $overrides): array
    {
        foreach ($overrides as $name => $value) {
            foreach (array_keys($base) as $existing) {
                if (strcasecmp((string) $existing, (string) $name) === 0) {
                    unset($base[$existing]);
                }
            }
            $base[$name] = $value;
        }

        return $base;
    }

    /**
     * Whether a response media type is text the transport hands over as a
     * decoded string (the same rule the transport uses), as opposed to a
     * binary body it base64-encodes.
     */
    private function isTextMediaType(string $mediaType): bool
    {
        $mediaType = strtolower($mediaType);
        return str_starts_with($mediaType, 'text/')
            || in_array($mediaType, ['application/json', 'application/xml', 'application/javascript'], true)
            || str_ends_with($mediaType, '+json')
            || str_ends_with($mediaType, '+xml');
    }

    /**
     * Build a query string from an array of key value pairs.
     *
     * When `$form` is true the result is encoded as
     * application/x-www-form-urlencoded (WHATWG form encoding), where a
     * space is encoded as `+`. Otherwise the result is a URL query string
     * where a space is encoded as `%20`.
     *
     * @param array<string, mixed> $params Query string parameters
     * @param bool                 $form   Encode as form body (space -> `+`)
     * @param array<string, bool>  $allowReservedKeys Set of parameter names
     *                                     (baseName => true) whose values keep RFC
     *                                     3986 reserved characters literal (OAS
     *                                     `allowReserved: true`). Empty by default,
     *                                     so every value is encoded as before.
     */
    private function buildQuery(array $params, bool $form = false, array $allowReservedKeys = []): string
    {
        if ($params === []) {
            return '';
        }

        $encode = static fn (string $s): string => $form
            ? str_replace('%20', '+', rawurlencode($s))
            : rawurlencode($s);

        $qs = '';
        foreach ($params as $k => $v) {
            $key = $encode($k);
            /* OAS allowReserved: values of a parameter declared
             * `allowReserved: true` keep RFC 3986 reserved characters literal
             * instead of percent-encoding them; everything else (spaces,
             * control chars, non-ASCII) is still encoded. The key is always
             * encoded normally. When the key is absent from the set the value
             * encoder is the default one, so encoding is byte-identical. */
            $encodeValue = isset($allowReservedKeys[$k])
                ? ValueSerializer::encodeQueryAllowingReserved(...)
                : $encode;
            if (is_array($v)) {
                foreach ($v as $vv) {
                    if (is_null($vv)) {
                        continue;
                    }
                    $qs .= $key;
                    $qs .= '=' . $encodeValue($this->queryValueText($vv));
                    $qs .= '&';
                }
            } else {
                if (is_null($v)) {
                    /* A null query value is dropped entirely (no key, no `=`).
                     * Every other SDK skips null query entries the same way
                     * (java `if (value != null)`, node `if (value == null)
                     * continue`, python pre-filters, ruby `query_params.compact`,
                     * dotnet `if (value != null)`). Without this `continue` the
                     * `$qs .= $key` below still ran for a null value, emitting a
                     * valueless `key&` token — a php-only malformed query string. */
                    continue;
                }
                $qs .= $key;
                $qs .= '=' . $encodeValue($this->queryValueText($v));
                $qs .= '&';
            }
        }

        return $qs !== '' ? substr($qs, 0, -1) : '';
    }

    /**
     * Render one query or form value as text. Scalars, date-times, durations,
     * UUIDs and backed enums take the canonical {@see ObjectSerializer::stringify}
     * form (so a date-time is RFC 3339 and an enum is its bare value, never a
     * JSON-encoded object or a quoted string); anything else is JSON-encoded.
     */
    private function queryValueText(mixed $value): string
    {
        if ($this->isFormScalar($value)) {
            return ObjectSerializer::stringify($value);
        }

        return (string) json_encode($value, JSON_UNESCAPED_SLASHES);
    }

    /**
     * Whether a value has a canonical {@see ObjectSerializer::stringify} text
     * form: a scalar, date-time, duration, UUID or backed enum.
     */
    private function isFormScalar(mixed $value): bool
    {
        return is_scalar($value)
            || $value instanceof \DateTimeInterface
            || $value instanceof \DateInterval
            || $value instanceof \BackedEnum
            || $value instanceof \Symfony\Component\Uid\Uuid;
    }

    /**
     * Serialize the request body based on content type.
     *
     * @param mixed       $body        Request body
     * @param string|null $contentType Content type
     * @param bool        $isMultipart Whether the request is multipart
     * @param bool        $rawBody     Whether the body is a `format: binary` value
     * @param array<string, bool> $allowReservedKeys Set of allow-reserved parameter
     *                                     names; a form field is under a `form:` prefix
     *
     * @return mixed Serialized body
     */
    private function serializeBody(
        mixed $body,
        ?string $contentType,
        bool $isMultipart,
        bool $rawBody = false,
        array $allowReservedKeys = []
    ): mixed {
        if ($body === null) {
            return null;
        }

        /* A body source is sent as it is read: it is never read here. */
        if ($body instanceof BodySource) {
            return $body;
        }

        /* A multipart body of any subtype (form-data, mixed, related) is a part map that the
         * transport encodes, keeping the declared subtype. */
        if ($isMultipart || (is_array($body) && str_starts_with(strtolower($contentType ?? ''), 'multipart/'))) {
            return $body;
        }

        /* A `format: binary` body is never routed through the JSON serializer,
         * whatever declared Content-Type the caller selected: the selector
         * only changes the header, the bytes are the caller's. */
        if (
            $rawBody
            || str_starts_with($contentType ?? '', 'image/')
            || $contentType === 'application/octet-stream'
        ) {
            /* A type:string format:binary body (e.g. a single-binary-body upload's image/jpeg
             * upload) must go on the wire as the RAW bytes under its DECLARED
             * Content-Type — never JSON-encoded, base64'd, or wrapped. When the
             * caller hands us an \SplFileObject we read its contents into the
             * byte string here so the transport sees a plain string body and
             * streams it verbatim (the non-array, is_string branch in both the
             * Default and PSR-18 clients). This mirrors the multipart file-part
             * idiom, which reads the same \SplFileObject via file_get_contents.
             * A raw stream resource is likewise drained to its bytes; an
             * already-string body passes through untouched. */
            if (is_array($body)) {
                /* The operation declares this binary content-type
                 * (application/octet-stream or image/*) ALONGSIDE
                 * multipart/form-data, so the API layer always builds a
                 * form-style map keyed by the declared parts. When the caller
                 * selects the raw-binary content-type we must NOT wrap the
                 * payload in a multipart envelope: unwrap the single binary
                 * part and stream its raw bytes under the selected
                 * Content-Type. Falling through to `return $body` would hand
                 * the array to the transport, whose `is_array($body)` branch
                 * emits multipart/form-data instead. Mirrors the
                 * single-binary-body path (e.g. a single-binary-body upload) that already
                 * sends raw bytes. */
                $body = $this->extractBinaryPart($body);
            }
            if ($body instanceof \SplFileObject) {
                $path = $body->getRealPath();
                $source = $path !== false ? $path : $body->getPathname();
                $contents = @file_get_contents($source);
                if ($contents === false) {
                    throw new \InvalidArgumentException(
                        sprintf('Failed to read request body file "%s"', $source)
                    );
                }
                return $contents;
            }
            if (is_resource($body)) {
                $contents = stream_get_contents($body);
                if ($contents === false) {
                    throw new \InvalidArgumentException('Failed to read request body stream');
                }
                return $contents;
            }
            if ($body instanceof \Psr\Http\Message\StreamInterface) {
                return (string) $body;
            }
            return $body;
        }

        if ($contentType === 'text/plain') {
            assert(is_string($body));
            return $body;
        }

        if ($contentType === 'application/x-www-form-urlencoded') {
            assert(is_array($body));
            /* A part encoding only applies to a multipart body: the form encoder sends the value. */
            $body = array_map(EncodedPart::unwrap(...), $body);
            /** @var array<string, mixed> $body */
            foreach ($body as $name => $value) {
                $values = is_array($value) && array_is_list($value) ? $value : [$value];
                foreach ($values as $element) {
                    if ($element !== null && !$this->isFormScalar($element)) {
                        /* A model, map or nested array has no defined form
                         * encoding without an OAS encoding block; failing here
                         * keeps a JSON blob or a language repr off the wire. */
                        throw new SerializationException(
                            'form-urlencoded field ' . $name . ' must be a scalar or array of scalars'
                        );
                    }
                }
            }
            /* A form field whose Encoding Object sets allowReserved is in the
             * set under a `form:` prefix; it keeps its reserved characters
             * literal, every other field is encoded as before. */
            $formReservedKeys = [];
            foreach ($allowReservedKeys as $key => $flag) {
                if (str_starts_with($key, 'form:')) {
                    $formReservedKeys[substr($key, 5)] = $flag;
                }
            }
            return $this->buildQuery($body, true, $formReservedKeys);
        }

        return ObjectSerializer::serialize($body);
    }

    /** The request target of a URL: its path and query, without the scheme and host. */
    private function requestTarget(string $url): string
    {
        $path = parse_url($url, PHP_URL_PATH);
        $query = parse_url($url, PHP_URL_QUERY);

        return (is_string($path) ? $path : '') . (is_string($query) && $query !== '' ? '?' . $query : '');
    }

    /**
     * Whether a 401 carries a challenge the digest authenticator accepts.
     *
     * @param array<string, string> $headers the response headers
     */
    private function acceptsChallenge(DigestAuthenticator $auth, array $headers): bool
    {
        foreach ($headers as $name => $value) {
            if (strcasecmp((string) $name, 'WWW-Authenticate') === 0) {
                return $auth->acceptChallenge($value);
            }
        }

        return false;
    }

    /**
     * Whether a request body can be sent again, which a replay after a token refresh needs: no body,
     * bytes, or a replayable {@see BodySource}. A stream or multipart parts cannot.
     */
    private function isReplayableBody(mixed $body): bool
    {
        return $body === null || is_string($body) || ($body instanceof BodySource && $body->isReplayable());
    }

    /**
     * Extract the single binary part from a form-style body map for a
     * raw-binary content-type selection.
     *
     * When an operation declares a raw-binary request content-type
     * (application/octet-stream or image/*) alongside multipart/form-data,
     * the API layer builds the body as an associative map keyed by the
     * declared parts. Selecting the raw-binary type means the wire body is
     * just that one binary value, so we pull out the first \SplFileObject /
     * resource / string part and discard the multipart framing. If no binary
     * part is present the original map is returned unchanged so the caller's
     * existing handling (and any error surfaced downstream) is preserved.
     *
     * @param array<array-key, mixed> $body Form-style body map
     *
     * @return mixed The single binary part, or the original map if none found
     */
    private function extractBinaryPart(array $body): mixed
    {
        foreach ($body as $value) {
            $value = EncodedPart::unwrap($value);
            if (
                $value instanceof \SplFileObject
                || is_resource($value)
                || $value instanceof \Psr\Http\Message\StreamInterface
                || is_string($value)
            ) {
                return $value;
            }
        }

        return $body;
    }
}
